    """The group Google shows the product in apart from its list: a carousel ("Ergonomic Chairs
    with Lumbar Support"), a price range ("Under $200"); null in the list itself.
    """
    photo_url: Optional[str]
    """The product's photo as the card shows it."""
    ids: GoogleShoppingProductsSearchRecordIds
    """Every id Google gives the card: the one another call or another tool may need."""
    source_url: str
    """The search these values were read from."""
    observed_at: str
    """When they were read, UTC."""


