class LacentraleListingsCheckOptions(TypedDict):
    """The options of ``lacentrale/listings/check``."""

    listing: str
    """A LaCentrale listing reference (E120356577), numeric URL id (69120356577), or public
    auto/moto/quad/scooter listing URL, as lacentrale/listings/get takes it. Required; no
    default. Tracking query parameters are ignored. Examples:
    "https://www.lacentrale.fr/auto-occasion-annonce-66104376140.html", "B104376140",
    "69120356577".
    """


class LacentraleListingsCheckRecord(TypedDict):
    """A record of ``lacentrale/listings/check``. With ``fields``, only the fields asked come."""

    object: Literal["listing_status"]
    listing_id: str
    """LaCentrale's reference of the listing (B104376140), the `id` of lacentrale/listings/search
    and lacentrale/listings/get.
    """
    url: str
    """The listing's address. For a listing given by its reference or numeric id that LaCentrale no
    longer holds, the auto address, which serves every vehicle family.
    """
    status: str
    """online: the listing is online. blocked: LaCentrale's own word for a listing it has taken
    offline and still holds, whether sold, withdrawn by its seller or expired (LaCentrale does
    not say which); its page says the listing is no longer available. gone: LaCentrale holds
    nothing under this id, a listing offline for long (two weeks offline are still held, three
    months are not) or an id that never was. Another word is LaCentrale's own for a state it
    adds, given as it is, in lower case.
    """
    published_date: Optional[str]
    """The day the listing first went online, as LaCentrale's search gives it. Null for a listing
    no longer online, and for a listing online that the search does not show yet.
    """
    updated_at: Optional[str]
    """When the listing was last updated, UTC, as LaCentrale's search gives it. Null as
    published_date.
    """
    publication_ended_at: Optional[str]
    """For a blocked listing, the end of its publication as LaCentrale keeps it: the moment it went
    offline, on the listings checked. Null otherwise.
    """
    source_url: str
    """The listing's page on lacentrale.fr."""
    observed_at: str
    """When they were read, UTC."""


