class SyncOperations:
    """The typed operations of ``Lobstr``, one attribute per source."""

    airbnb: _AirbnbSource
    booking: _BookingSource
    facebook_marketplace: _FacebookMarketplaceSource
    google_lens: _GoogleLensSource
    google_maps: _GoogleMapsSource
    google_news: _GoogleNewsSource
    google_shopping: _GoogleShoppingSource
    lacentrale: _LacentraleSource
    leboncoin: _LeboncoinSource
    realtor: _RealtorSource
    sales_navigator: _SalesNavigatorSource
    seloger: _SelogerSource
    tripadvisor: _TripadvisorSource
    websites: _WebsitesSource
    x: _XSource

    def _init_operations(self) -> None:
        client = cast("Lobstr", self)
        self.airbnb = _AirbnbSource(client)
        self.booking = _BookingSource(client)
        self.facebook_marketplace = _FacebookMarketplaceSource(client)
        self.google_lens = _GoogleLensSource(client)
        self.google_maps = _GoogleMapsSource(client)
        self.google_news = _GoogleNewsSource(client)
        self.google_shopping = _GoogleShoppingSource(client)
        self.lacentrale = _LacentraleSource(client)
        self.leboncoin = _LeboncoinSource(client)
        self.realtor = _RealtorSource(client)
        self.sales_navigator = _SalesNavigatorSource(client)
        self.seloger = _SelogerSource(client)
        self.tripadvisor = _TripadvisorSource(client)
        self.websites = _WebsitesSource(client)
        self.x = _XSource(client)


# -- AsyncLobstr's typed operations


class _AsyncAirbnbHomesGetOperation:
    """``airbnb/homes/get``: One Airbnb home whole, as its page shows it: its description, rooms,
    beds and photos, every amenity, its rating and what guests say, the host, the house rules,
    where it is, and its price for your dates.
    """

    operation = "airbnb/homes/get"

    def __init__(self, client: "AsyncLobstr") -> None:
        self._client = client

    async def __call__(
        self,
        *,
        home: str,
        checkin: Optional[str] = None,
        checkout: Optional[str] = None,
        adults: Optional[int] = None,
        children: Optional[int] = None,
        infants: Optional[int] = None,
        pets: Optional[int] = None,
        currency: Optional[str] = None,
        locale: Optional[str] = None,
        fields: _Fields = None,
        timeout_s: Optional[int] = None,
        idempotency_key: Optional[str] = None,
    ) -> "AsyncRun[AirbnbHomesGetRecord]":
        """One Airbnb home whole, as its page shows it: its description, rooms, beds and photos,
        every amenity, its rating and what guests say, the host, the house rules, where it is,
        and its price for your dates.

        Args:
            home: The home: its id on Airbnb (a search's `id`), or its page's address as the
                browser shows it (https://www.airbnb.com/rooms/<id>?...), from any of Airbnb's sites
                (fr.airbnb.com, airbnb.co.uk...). The dates and guests in the address (check_in,
                check_out, adults...) are the stay priced, unless `checkin`, `checkout` and the
                guests below say another. A search's address is refused with what to do
                (`invalid_home`). Examples: "1013402113840724461",
                "https://www.airbnb.com/rooms/1013402113840724461?check_in=2026-12-14&check_out=2026-12-17&adults=2".
            checkin: The first night of the stay to price, YYYY-MM-DD, with `checkout`. None by
                default (no price). Examples: "2026-12-14".
            checkout: The day the stay ends, YYYY-MM-DD, after `checkin`. Examples:
                "2026-12-17".
            adults: The adults of the stay. Default: 1.
            children: The children of the stay, from 2 to the age the home says
                (`guests.children_max_age`, 12 or 17). Default: 0.
            infants: The infants of the stay (under 2). Default: 0.
            pets: The pets of the stay. Default: 0.
            currency: The currency of the prices, ISO 4217 (USD, EUR, GBP...), as Airbnb
                converts them. Default: "USD". Examples: "USD".
            locale: The language of the page: Airbnb's own words, and the host's texts as Airbnb
                translates them (`name`, `description`; their `_original` keeps the host's own
                words). Default: "en". Examples: "en".
            fields: Only these fields of each record, by path (``name``, ``address.city``);
                ``object``, ``id`` and ``position`` always come.
            timeout_s: The most seconds the API waits for the site, up to the operation's
                maximum.
            idempotency_key: Sent as ``Idempotency-Key``; a UUID4 when left out, kept across
                retries.

        Returns:
            The answer, its record (``AirbnbHomesGetRecord``) in ``results``.

        The contract: https://api.lobstr.io/v2/catalog/airbnb/homes/get
        """
        run = await self._client.run(
            "airbnb/homes/get",
            _options(
                {
                    "home": home,
                    "checkin": checkin,
                    "checkout": checkout,
                    "adults": adults,
                    "children": children,
                    "infants": infants,
                    "pets": pets,
                    "currency": currency,
                    "locale": locale,
                }
            ),
            fields=fields,
            timeout_s=timeout_s,
            idempotency_key=idempotency_key,
        )
        return cast("AsyncRun[AirbnbHomesGetRecord]", run)


class _AsyncAirbnbHomesSearchOperation:
    """``airbnb/homes/search``: The homes of an Airbnb search, 18 a page, each with its name, place
    and coordinates, rating, price for the dates with its breakdown, beds and baths, badges and
    photos.
    """

    operation = "airbnb/homes/search"

    def __init__(self, client: "AsyncLobstr") -> None:
        self._client = client

    async def __call__(
        self,
        *,
        search: str,
        page: Optional[int] = None,
        currency: Optional[str] = None,
        locale: Optional[str] = None,
        cursor: Optional[str] = None,
        fields: _Fields = None,
        limit: Optional[int] = None,
        timeout_s: Optional[int] = None,
        idempotency_key: Optional[str] = None,
    ) -> "AsyncRun[AirbnbHomesSearchRecord]":
        """The homes of an Airbnb search, 18 a page, each with its name, place and coordinates,
        rating, price for the dates with its breakdown, beds and baths, badges and photos.

        Args:
            search: The search, as Airbnb writes it: the address of its results page, copied
                from the browser (https://www.airbnb.com/s/<place>/homes?...), from any of Airbnb's
                sites (fr.airbnb.com, airbnb.co.uk...). Every parameter of the address is the search
                (place, dates, guests, filters, the map's corners) and is kept; what marks a visit
                (session ids, the page's own cursor) is ignored. A search of experiences or
                services, or a home's page, is refused with what to do (`invalid_search`). Examples:
                "https://www.airbnb.com/s/Paris--France/homes?place_id=ChIJD7fiBh9u5kcRYJSMaMOCCwQ&checkin=2026-12-10&checkout=2026-12-13&adults=2".
            page: The page to start at, 18 homes a page, up to Airbnb's 15; then follow `next`.
                Default: 1.
            currency: The currency of the prices, ISO 4217 (USD, EUR, GBP...), as Airbnb
                converts them. Default: "USD". Examples: "USD".
            locale: The language of Airbnb's own words (titles, badges, beds, price lines): en,
                fr, de, es, pt-BR... A home's name is its host's, in the language they wrote it.
                Default: "en". Examples: "en".
            cursor: Where to go on, from `next` in an answer, as it is: opaque, and only for the
                search it was given with (otherwise `invalid_cursor`).
            fields: Only these fields of each record, by path (``name``, ``address.city``);
                ``object``, ``id`` and ``position`` always come.
            limit: Only the first 1 to 1,000 records of the page; the call costs the same.
            timeout_s: The most seconds the API waits for the site, up to the operation's
                maximum.
            idempotency_key: Sent as ``Idempotency-Key``; a UUID4 when left out, kept across
                retries.

        Returns:
            The answer, its records (``AirbnbHomesSearchRecord``) in ``results``. ``await
                run.next_page()`` gives the following page; ``.iterate(...)`` every record.

        The contract: https://api.lobstr.io/v2/catalog/airbnb/homes/search
        """
        run = await self._client.run(
            "airbnb/homes/search",
            _options(
                {
                    "search": search,
                    "page": page,
                    "currency": currency,
                    "locale": locale,
                    "cursor": cursor,
                }
            ),
            fields=fields,
            limit=limit,
            timeout_s=timeout_s,
            idempotency_key=idempotency_key,
        )
        return cast("AsyncRun[AirbnbHomesSearchRecord]", run)

    def iterate(
        self,
        *,
        search: str,
        page: Optional[int] = None,
        currency: Optional[str] = None,
        locale: Optional[str] = None,
        cursor: Optional[str] = None,
        fields: _Fields = None,
        limit: Optional[int] = None,
        timeout_s: Optional[int] = None,
        max_records: Optional[int] = None,
        max_pages: Optional[int] = None,
    ) -> "AsyncIterator[AirbnbHomesSearchRecord]":
        """Every page's records of ``airbnb/homes/search`` (``async for``), following ``next``
        until it is null or a cap is hit.

        Args:
            search: The search, as Airbnb writes it: the address of its results page, copied
                from the browser (https://www.airbnb.com/s/<place>/homes?...), from any of Airbnb's
                sites (fr.airbnb.com, airbnb.co.uk...). Every parameter of the address is the search
                (place, dates, guests, filters, the map's corners) and is kept; what marks a visit
                (session ids, the page's own cursor) is ignored. A search of experiences or
                services, or a home's page, is refused with what to do (`invalid_search`). Examples:
                "https://www.airbnb.com/s/Paris--France/homes?place_id=ChIJD7fiBh9u5kcRYJSMaMOCCwQ&checkin=2026-12-10&checkout=2026-12-13&adults=2".
            page: The page to start at, 18 homes a page, up to Airbnb's 15; then follow `next`.
                Default: 1.
            currency: The currency of the prices, ISO 4217 (USD, EUR, GBP...), as Airbnb
                converts them. Default: "USD". Examples: "USD".
            locale: The language of Airbnb's own words (titles, badges, beds, price lines): en,
                fr, de, es, pt-BR... A home's name is its host's, in the language they wrote it.
                Default: "en". Examples: "en".
            cursor: Where to go on, from `next` in an answer, as it is: opaque, and only for the
                search it was given with (otherwise `invalid_cursor`).
            fields: Only these fields of each record, by path (``name``, ``address.city``);
                ``object``, ``id`` and ``position`` always come.
            limit: Only the first 1 to 1,000 records of the page; the call costs the same.
            timeout_s: The most seconds the API waits for the site, up to the operation's
                maximum.
            max_records: Stop after this many records.
            max_pages: Stop after this many pages (each page is one call, at the operation's
                price).
        """
        records = self._client.iterate(
            "airbnb/homes/search",
            _options(
                {
                    "search": search,
                    "page": page,
                    "currency": currency,
                    "locale": locale,
                    "cursor": cursor,
                }
            ),
            max_records=max_records,
            max_pages=max_pages,
            fields=fields,
            limit=limit,
            timeout_s=timeout_s,
        )
        return cast("AsyncIterator[AirbnbHomesSearchRecord]", records)


